self.addEventListener("push",t=>{let n={};try{n=t.data?t.data.json():{}}catch{n={title:"Announcement",body:t.data?.text()}}t.waitUntil(self.registration.showNotification(n.title||"Announcement",{body:n.body,tag:n.tag,icon:"/icons/icon-192x192.png",badge:"/icons/icon-96x96.png",data:{url:n.url||"/"}}))}),self.addEventListener("notificationclick",t=>{t.notification.close();let n=t.notification.data?.url||"/";t.waitUntil(clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let i of t)if("focus"in i)return i.navigate(n),i.focus();return clients.openWindow(n)}))});